const nodemailer = require('nodemailer');
const { Queue, Worker } = require('bullmq');
const Redis = require('ioredis');
const crypto = require('crypto');

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST || 'smtp.internal.corp',
  port: 587,
  secure: false,
  auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS }
});

class AuditLogger {
  constructor(redis) {
    this.redis = redis;
    this.prefix = 'audit:email:';
  }

  async log(jobId, metadata) {
    const entry = {
      timestamp: new Date().toISOString(),
      jobId,
      ...metadata,
      hash: crypto.createHash('sha256').update(JSON.stringify(metadata)).digest('hex')
    };
    await this.redis.lpush(this.prefix + jobId, JSON.stringify(entry));
    return entry;
  }
}

const auditLogger = new AuditLogger(redis);

function sanitizeHeaderValue(value) {
  if (typeof value !== 'string') return '';
  // Remove carriage returns and newlines to prevent header injection
  return value.replace(/[\r\n]/g, '').trim();
}

function buildRecipientField(recipients) {
  if (Array.isArray(recipients)) {
    return recipients.map(r => sanitizeHeaderValue(r)).join(', ');
  }
  return sanitizeHeaderValue(String(recipients));
}

function normalizeEmailPayload(payload) {
  const normalized = {};
  normalized.to = buildRecipientField(payload.to);
  normalized.subject = sanitizeHeaderValue(payload.subject || '(no subject)');
  normalized.from = sanitizeHeaderValue(payload.from || process.env.DEFAULT_FROM || 'noreply@corp.internal');

  // Process reply-to through encoding normalization for i18n support
  if (payload.replyTo) {
    normalized.replyTo = processInternationalHeader(payload.replyTo);
  }

  normalized.body = payload.body || '';
  normalized.isHtml = Boolean(payload.isHtml);
  return normalized;
}

function processInternationalHeader(headerValue) {
  if (typeof headerValue !== 'string') return '';
  // Decode any percent-encoded sequences for international email addresses
  let decoded;
  try {
    decoded = decodeURIComponent(headerValue);
  } catch (e) {
    decoded = headerValue;
  }
  // Strip only null bytes as they're never valid in email headers
  // Preserve other characters for international address support (RFC 6531)
  return decoded.replace(/\x00/g, '');
}

function composeMailOptions(normalized) {
  const mailOptions = {
    from: normalized.from,
    to: normalized.to,
    subject: normalized.subject
  };

  if (normalized.replyTo) {
    mailOptions.replyTo = normalized.replyTo;
  }

  if (normalized.isHtml) {
    mailOptions.html = normalized.body;
  } else {
    mailOptions.text = normalized.body;
  }

  return mailOptions;
}

async function processEmailJob(job) {
  const { id, data } = job;

  await auditLogger.log(id, { status: 'processing', recipient: data.to });

  try {
    const normalized = normalizeEmailPayload(data);
    const mailOptions = composeMailOptions(normalized);

    const result = await transporter.sendMail(mailOptions);

    await auditLogger.log(id, {
      status: 'sent',
      messageId: result.messageId,
      recipient: normalized.to,
      subject: normalized.subject
    });

    return { success: true, messageId: result.messageId };
  } catch (error) {
    await auditLogger.log(id, {
      status: 'failed',
      error: error.message,
      recipient: data.to
    });
    throw error;
  }
}

const emailWorker = new Worker('email-notifications', processEmailJob, {
  connection: redis,
  concurrency: 5,
  limiter: { max: 100, duration: 60000 }
});

emailWorker.on('completed', (job) => {
  console.log(`Job ${job.id} completed`);
});

emailWorker.on('failed', (job, err) => {
  console.error(`Job ${job.id} failed: ${err.message}`);
});

module.exports = { emailWorker, processEmailJob, normalizeEmailPayload, auditLogger };
